### 第 9 题（电子学会五级模拟·STL）以下代码的输出是？（ ）

```cpp
string s = "hello";
s += " world";
cout << s.substr(6, 5);
```

- A. `hello`
- B. ` world`
- C. `world`
- D. `ello`

questions.explanation:
二分答案 x（等长小木段长度）：x 越大能锯出的总段数越少，满足单调性。check(x) 统计 Σ⌊aᵢ/x⌋ 是否 ≥ k。若全部锯成 1 段仍不足 k 段，则 ans 为 0。时间复杂度 O(n log max(a))。参考程序：

```cpp
#include <iostream>
#include <algorithm>
using namespace std;

typedef long long ll;
ll a[100005];
int n; ll k;

bool check(ll x) {
    ll cnt = 0;
    for (int i = 0; i < n; i++) {
        cnt += a[i] / x;
        if (cnt >= k) return true;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> n >> k;
    ll mx = 0;
    for (int i = 0; i < n; i++) { cin >> a[i]; mx = max(mx, a[i]); }
    ll lo = 1, hi = mx, ans = 0;
    while (lo <= hi) {
        ll mid = (lo + hi) / 2;
        if (check(mid)) { ans = mid; lo = mid + 1; }
        else hi = mid - 1;
    }
    cout << ans << "\n";
    return 0;
}
```

将区间按左端点 l 升序排序，维护当前合并区间 [L, R]：下一区间 l ≤ R 则并入（R 取 max），否则开新区间并计数。排序 O(n log n)，遍历 O(n)。参考程序：

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long ll;

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int n; cin >> n;
    vector<pair<ll, ll>> seg(n);
    for (int i = 0; i < n; i++) cin >> seg[i].first >> seg[i].second;
    sort(seg.begin(), seg.end());
    int ans = 1;
    ll L = seg[0].first, R = seg[0].second;
    for (int i = 1; i < n; i++) {
        if (seg[i].first <= R) R = max(R, seg[i].second);
        else { ans++; L = seg[i].first; R = seg[i].second; }
    }
    cout << ans << "\n";
    return 0;
}
```

用 set 存小明的好友（去重），遍历小红的好友，若在 set 中出现则计数。

参考程序：

```cpp
#include <iostream>
#include <set>
#include <string>
using namespace std;

int main()
{
    int n, m, ans = 0;
    string s;
    set<string> st;
    cin >> n >> m;
    for (int i = 0; i < n; i++) { cin >> s; st.insert(s); }
    for (int i = 0; i < m; i++) { cin >> s; if (st.count(s)) ans++; }
    cout << ans << endl;
    return 0;
}
```

排序后双指针贪心：l=0, r=n-1，若 a[l]+a[r]≤W 则配对（l++ r--），否则重单独装（r--），每步盒数+1。

参考程序：

```cpp
#include <iostream>
#include <algorithm>
using namespace std;

typedef long long ll;
ll a[100005];

int main()
{
    int n, ans = 0;
    ll W;
    cin >> n >> W;
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a, a + n);
    int l = 0, r = n - 1;
    while (l <= r)
    {
        if (l == r) { ans++; break; }
        if (a[l] + a[r] <= W) { ans++; l++; r--; }
        else { ans++; r--; }
    }
    cout << ans << endl;
    return 0;
}
```
